//! Replays the pinned CesiumJS capture in
//! `tests/data/scene-voxel-draw-commands.json` (generated by
//! `tools/cesium/generate-scene-voxel-draw-commands.mjs`) through the Rust
//! `VoxelRenderResources`, `processVoxelProperties` and
//! `buildVoxelDrawCommands` ports. Shader source, defines, attribute locations
//! and the render state are compared exactly.
use cesium_rs::core::*;
use cesium_rs::scene::*;
use serde_json::Value;
use std::cell::RefCell;
use std::rc::Rc;

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-voxel-draw-commands.json")).unwrap()
}

fn shape_for(kind: &str) -> Box<dyn VoxelShape> {
    let shape_type = VoxelShapeType::from_str_value(kind).unwrap();
    let mut shape = shape_type.create_shape();
    let (min, max, model) = match shape_type {
        VoxelShapeType::Ellipsoid => (
            Cartesian3::new(-std::f64::consts::PI, -std::f64::consts::FRAC_PI_2, 0.0),
            Cartesian3::new(std::f64::consts::PI, std::f64::consts::FRAC_PI_2, 1000.0),
            Matrix4::from_scale(Ellipsoid::WGS84.radii),
        ),
        VoxelShapeType::Cylinder => (
            Cartesian3::new(0.0, -std::f64::consts::PI, -1.0),
            Cartesian3::new(1.0, std::f64::consts::PI, 1.0),
            Matrix4::IDENTITY,
        ),
        VoxelShapeType::Box => (Cartesian3::new(-1.0, -1.0, -1.0), Cartesian3::new(1.0, 1.0, 1.0), Matrix4::IDENTITY),
    };
    assert!(shape.update(model, min, max, Some(min), Some(max)));
    shape
}

const DEFAULT_CUSTOM_FRAGMENT: &str =
    "void fragmentMain(FragmentInput fsInput, inout czm_modelMaterial material)\n{\n    material.diffuse = vec3(1.0);\n    material.alpha = 1.0;\n}";

fn texture_resolution(length: usize) -> [u32; 2] {
    if length == 0 {
        return [0, 0];
    }
    let x = length.min(4096);
    let y = length.div_ceil(x);
    [x as u32, (y * 2) as u32]
}

#[test]
fn voxel_shader_and_render_state_match_pinned_cesium() {
    for case in fixture()["cases"].as_array().unwrap() {
        let settings = &case["settings"];
        let kind = settings["type"].as_str().unwrap();
        let shape_type = VoxelShapeType::from_str_value(kind).unwrap();
        let shape = shape_for(kind);
        let clipping_length = settings["clipping"].as_u64().unwrap() as usize;
        let clipping = if clipping_length == 0 {
            None
        } else {
            let planes = (0..clipping_length).map(|i| {
                ClippingPlane::handle(Cartesian3::new(0.0, 0.0, 1.0), i as f64 * 0.25)
            });
            let mut collection = ClippingPlaneCollection::new(planes);
            collection.union_clipping_regions = settings["union"].as_bool().unwrap();
            Some(Rc::new(RefCell::new(collection)))
        };
        let statistics = settings["statistics"].as_bool().unwrap();
        let property_info = VoxelPropertyInfo {
            names: if statistics { vec!["density".into(), "velocity".into(), "flag".into()] } else { vec![] },
            types: if statistics {
                vec![MetadataType::Scalar, MetadataType::Vec3, MetadataType::Vec4]
            } else {
                vec![]
            },
            component_types: if statistics {
                vec![
                    MetadataComponentType::Float32,
                    MetadataComponentType::Uint8,
                    MetadataComponentType::Float32,
                ]
            } else {
                vec![]
            },
            minimum_values: statistics.then(|| vec![vec![0.0], vec![0.0, 0.0, 0.0], vec![0.0; 4]]),
            maximum_values: statistics.then(|| vec![vec![1.0], vec![2.0, 3.0, 4.0], vec![1.0; 4]]),
        };
        let uniform_names = vec!["u_stepSize".to_string()];
        let mut resources = VoxelRenderResources::new(VoxelRenderResourcesOptions {
            custom_fragment_shader_text: Some(DEFAULT_CUSTOM_FRAGMENT),
            custom_uniforms: &[],
            uniform_names: &uniform_names,
            clipping_planes: clipping.clone(),
            shape: shape.as_ref(),
            shape_type,
            metadata_order: if settings["yUp"].as_bool().unwrap() {
                VoxelMetadataOrder::YUp
            } else {
                VoxelMetadataOrder::ZUp
            },
            depth_test: settings["depthTest"].as_bool().unwrap(),
            padding_before: if settings["padding"].as_bool().unwrap() {
                Cartesian3::new(1.0, 1.0, 1.0)
            } else {
                Cartesian3::ZERO
            },
            padding_after: if settings["padding"].as_bool().unwrap() {
                Cartesian3::new(2.0, 2.0, 2.0)
            } else {
                Cartesian3::ZERO
            },
            use_log_depth: settings["logDepth"].as_bool().unwrap(),
            sample_count: settings["sampleCount"].as_u64().unwrap() as usize,
        });
        process_voxel_properties(&mut resources, &property_info).unwrap();
        let render_bound_length = shape.render_bound_plane_handles().len();
        let commands = build_voxel_draw_commands(
            &mut resources,
            texture_resolution(clipping_length),
            texture_resolution(render_bound_length),
        )
        .unwrap();
        let expected = &case["shader"];
        let actual = &commands.shader;
        let mut actual_defines = actual.1.defines.clone();
        let mut expected_defines: Vec<String> =
            expected["defines"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().into()).collect();
        actual_defines.sort();
        expected_defines.sort();
        assert_eq!(actual_defines, expected_defines, "fragment defines for {settings}");
        assert_eq!(actual.0.sources.join("\n"), expected["vertex"].as_str().unwrap(), "vertex source for {settings}");
        compare_source(&actual.1.sources.join("\n"), expected["fragment"].as_str().unwrap(), "fragment", settings);
        assert_eq!(actual.0.defines, expected["vertexDefines"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect::<Vec<_>>());
        assert_eq!(resources.uniform_names, {
            let mut names: Vec<String> = case["command"]["uniformNames"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_str().unwrap().into())
                .collect();
            names.sort();
            names
        });
        let expected_state = &case["renderState"];
        assert_eq!(commands.render_state.cull.face, expected_state["cull"]["face"].as_u64().unwrap() as u32);
        assert_eq!(commands.render_state.depth_mask, expected_state["depthMask"].as_bool().unwrap());
        assert_eq!(
            commands.render_state.depth_test.enabled,
            expected_state["depthTest"]["enabled"].as_bool().unwrap()
        );
        assert_eq!(
            commands.render_state.blending.enabled,
            expected_state["blending"]["enabled"].as_bool().unwrap()
        );
        assert_eq!(
            commands.render_state.blending.function_source_rgb,
            expected_state["blending"]["functionSourceRgb"].as_u64().unwrap() as u32
        );
        assert_eq!(
            commands.render_state.blending.function_destination_rgb,
            expected_state["blending"]["functionDestinationRgb"].as_u64().unwrap() as u32
        );
        // The pick variants are the same builder with one extra define.
        let normal_fragment = commands.shader.1.sources.join("\n");
        assert_eq!(commands.shader_pick.1.sources.join("\n"), normal_fragment);
        assert_eq!(commands.shader_pick_voxel.1.sources.join("\n"), normal_fragment);
        assert!(commands.shader_pick.1.defines.contains(&"PICKING".to_string()));
        assert!(commands.shader_pick_voxel.1.defines.contains(&"PICKING_VOXEL".to_string()));
        if settings["clipping"].as_u64().unwrap() > 0 {
            assert!(commands.shader.1.sources[0].contains("vec4 getClippingPlane(highp sampler2D"));
        }
    }
}

fn compare_source(actual: &str, expected: &str, label: &str, settings: &Value) {
    if actual == expected {
        return;
    }
    let actual_chars: Vec<char> = actual.chars().collect();
    let expected_chars: Vec<char> = expected.chars().collect();
    let mut index = 0;
    while index < actual_chars.len() && index < expected_chars.len() && actual_chars[index] == expected_chars[index] {
        index += 1;
    }
    let start = index.saturating_sub(80);
    let actual_snippet: String = actual_chars[start..(index + 160).min(actual_chars.len())].iter().collect();
    let expected_snippet: String = expected_chars[start..(index + 160).min(expected_chars.len())].iter().collect();
    panic!("{label} source differs at char {index} for {settings}\nactual:   {actual_snippet:?}\nexpected: {expected_snippet:?}");
}

#[test]
fn voxel_property_functions_are_present_in_the_shader() {
    let shape = shape_for("BOX");
    let mut resources = VoxelRenderResources::new(VoxelRenderResourcesOptions {
        custom_fragment_shader_text: None,
        custom_uniforms: &[],
        uniform_names: &[],
        clipping_planes: None,
        shape: shape.as_ref(),
        shape_type: VoxelShapeType::Box,
        metadata_order: VoxelMetadataOrder::YUp,
        depth_test: true,
        padding_before: Cartesian3::ZERO,
        padding_after: Cartesian3::ZERO,
        use_log_depth: false,
        sample_count: 1,
    });
    let info = VoxelPropertyInfo {
        names: vec!["density".into()],
        types: vec![MetadataType::Scalar],
        component_types: vec![MetadataComponentType::Float32],
        minimum_values: Some(vec![vec![0.0]]),
        maximum_values: Some(vec![vec![1.0]]),
    };
    process_voxel_properties(&mut resources, &info).unwrap();
    let (_, fragment) = resources.sources();
    let source = fragment.sources.join("\n");
    assert!(source.contains("struct PropertyStatistics_density"));
    assert!(source.contains("Properties getPropertiesFromMegatextureAtUv(vec3 texcoord)"));
    assert!(source.contains("metadataStatistics.density.min = 0.0;"));
    assert!(source.contains("properties.density = texture(u_megatextureTextures[0], texcoord).r;"));
}
